// Splits AGENTS.md's TypeScript style sections (5-7) into .claude/rules/typescript-code-style.md,
// a path-scoped rule Claude Code loads only while editing a matching source file, instead of on
// every session regardless of what is being edited (AGENTS.md 3, P0-18). AGENTS.md stays the only
// hand-edited source; `--check` verifies the generated file still matches it, wired into
// `lint:generated` the same way `npm pack --dry-run` backs `pack:check`.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const repoRoot = join(import.meta.dirname, '..');
const agentsPath = join(repoRoot, 'AGENTS.md');
const outPath = join(repoRoot, '.claude', 'rules', 'typescript-code-style.md');

const SECTION_START = '## 5. TypeScript code style';
const SECTION_END = '## 8. Branches, commits and pull requests';

const RULE_PATHS = ['packages/**/*.ts', 'examples/**/*.ts', 'scripts/**/*.mjs', 'scripts/**/*.cjs'];

function extractSection(agentsSource) {
  const startIndex = agentsSource.indexOf(SECTION_START);
  const endIndex = agentsSource.indexOf(SECTION_END);
  if (startIndex === -1 || endIndex === -1 || endIndex <= startIndex) {
    throw new Error(
      `Could not find AGENTS.md's TypeScript style sections between "${SECTION_START}" and "${SECTION_END}".`,
    );
  }
  return agentsSource.slice(startIndex, endIndex).trimEnd();
}

function render(section) {
  const pathsYaml = `[${RULE_PATHS.map((path) => `'${path}'`).join(', ')}]`;
  return [
    '---',
    `paths: ${pathsYaml}`,
    '---',
    '',
    '<!-- Generated by scripts/generate-claude-rules.mjs from AGENTS.md sections 5-7. -->',
    '<!-- Do not edit by hand: edit AGENTS.md and run "npm run generate". -->',
    '',
    section,
    '',
  ].join('\n');
}

function readExisting() {
  try {
    return readFileSync(outPath, 'utf8');
  } catch (error) {
    if (error instanceof Error && 'code' in error && error.code === 'ENOENT') {
      return undefined;
    }
    throw error;
  }
}

const agentsSource = readFileSync(agentsPath, 'utf8');
const rendered = render(extractSection(agentsSource));
const checkOnly = process.argv.includes('--check');

if (checkOnly) {
  if (readExisting() !== rendered) {
    console.error(`${outPath} does not match AGENTS.md. Run "npm run generate" and commit the result.`);
    process.exit(1);
  }
  console.log(`${outPath} is up to date.`);
} else {
  mkdirSync(join(repoRoot, '.claude', 'rules'), { recursive: true });
  writeFileSync(outPath, rendered);
  console.log(`Generated ${outPath}`);
}
